import{_ as a,o as i,c as l,j as e,a as n,a3 as s}from"./chunks/framework.z_KJ15Ep.js";const o="/bilder/schueler/k-ao-a-einstellungen-reiter-aktivieren.png",t="/bilder/schueler/k-ao-a-massnahme-anlegen.png",u="/bilder/schueler/k-ao-a-03.png",d="/bilder/schueler/k-ao-a-04.png",f=JSON.parse('{"title":"KAoA-Module erfassen und archivieren","description":"","frontmatter":{"title":"KAoA-Module erfassen und archivieren","source_pageid":626,"source_revision":5069},"headers":[],"relativePath":"schild3/schueler/kaoa-schueler.md","filePath":"schild3/schueler/kaoa-schueler.md"}'),h={name:"schild3/schueler/kaoa-schueler.md"};function g(c,r,p,m,A,b){return i(),l("div",null,[...r[0]||(r[0]=[e("h1",{id:"kaoa-module-erfassen-und-archivieren",tabindex:"-1"},[n("KAoA-Module erfassen und archivieren "),e("a",{class:"header-anchor",href:"#kaoa-module-erfassen-und-archivieren","aria-label":'Permalink to "KAoA-Module erfassen und archivieren"'},"​")],-1),e("p",null,"Dokumentieren Sie absolvierte Module der beruflichen Orientierung. Die verfügbaren Module richten sich nach dem Jahrgang; der KAoA-Reiter muss bei Bedarf erst eingeblendet werden.",-1),e("p",null,[n("In diesem Reiter können für den ausgewählten Schüler Module der beruflichen Orientierung von "),e("em",null,'"Kein Abschluss ohne Anschluss - Übergang Schule-Beruf NRW"'),n(", KAoA, verwaltet und archiviert werden.")],-1),e("p",null,"Die Module sind einheitlich vorgegeben und sind in SchILD-NRW bereits hinterlegt. Die zur Verfügung stehenden Module richten sich nach dem jeweils ausgewählten Jahrgang.",-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Maßnahmen der beruflichen Orientierung im Rahmen von KAoA beginnen an den weiterführenden Schulen mit dem Jahrgang 8.")],-1),s('<h2 id="anzeigen-des-kaoa-reiters" tabindex="-1">Anzeigen des KAoA-Reiters <a class="header-anchor" href="#anzeigen-des-kaoa-reiters" aria-label="Permalink to &quot;Anzeigen des KAoA-Reiters&quot;">​</a></h2><p><a href="/bilder/schueler/k-ao-a-einstellungen-reiter-aktivieren.png"><img src="'+o+'" alt="Anzeigen des KAoA-Reiters unter Verwaltung ➜ Einstellungen ➜ Globale Einstellungen: Allgemeines ➜ Ansicht." loading="lazy"></a></p><p><em>Anzeigen des KAoA-Reiters unter Verwaltung ➜ Einstellungen ➜ Globale Einstellungen: Allgemeines ➜ Ansicht.</em></p><p>Blenden Sie den Reiter <strong>KAoA</strong> zunächst über die globalen Einstellungen ein.</p><p>Der Reiter kann über <em>Verwaltung ➜ Einstellungen ➜ Globale Einstellungen</em> und dann in <em>Allgemeines ➜ Ansicht</em> ➜ <strong>Karteireiter &#39;KAoA&quot; zeigen</strong> per Haken aktiviert und deaktiviert werden.</p><h2 id="anlegen-von-absolvierten-modulen" tabindex="-1">Anlegen von absolvierten Modulen <a class="header-anchor" href="#anlegen-von-absolvierten-modulen" aria-label="Permalink to &quot;Anlegen von absolvierten Modulen&quot;">​</a></h2><p><a href="/bilder/schueler/k-ao-a-massnahme-anlegen.png"><img src="'+t+'" alt="Anlegen von absolvierten Modulen unter Schüler ➜ KAoA." loading="lazy"></a></p><p><em>Anlegen von absolvierten Modulen unter Schüler ➜ KAoA.</em></p><p>Im entsprechenden Reiter können für ausgewählten Schüler absolvierte Module angelegt und so archiviert werden.</p><p><a href="/bilder/schueler/k-ao-a-03.png"><img src="'+u+'" alt="Das Auswahlfenster zur Auswahl der absolvierten Module." loading="lazy"></a></p><p><em>Das Auswahlfenster zur Auswahl der absolvierten Module.</em></p><p>Klicken Sie auf <strong>+</strong>. Im Auswahlfenster wählen Sie nacheinander <strong>Kategorie</strong>, <strong>Merkmal</strong> und <strong>Zusatzmerkmal</strong> für den Jahrgang aus.</p><p>Die auswählbaren weiteren Merkmale hängen vom jeweils vorherigen ab, so dass nur zulässige Kombinationen eingeben werden können.</p><p>Ein Klick auf das &quot;<strong>-</strong>&quot; löscht ein fälschlich zugeordnetes Merkmal.</p><h2 id="gruppenprozesse" tabindex="-1">Gruppenprozesse <a class="header-anchor" href="#gruppenprozesse" aria-label="Permalink to &quot;Gruppenprozesse&quot;">​</a></h2><p><a href="/bilder/schueler/k-ao-a-04.png"><img src="'+d+'" alt="Anlegen von absolvierten Modulen per Gruppenprozess unter Gruppenprozesse: Allgemein ➜ KAoA." loading="lazy"></a></p><p><em>Anlegen von absolvierten Modulen per Gruppenprozess unter Gruppenprozesse: Allgemein ➜ KAoA.</em></p><p>Da häufig Klassen oder Jahrgangsstufen zusammen die Module von KAoA absolvieren, bietet es sich an, die Merkmale wie im Beispiel dargestellt per Gruppenprozess zuzuweisen.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=KAoA_(Sch%C3%BCler)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5069.</p>',20)])])}const k=a(h,[["render",g]]);export{f as __pageData,k as default};
